{"version":1,"taskId":"5a950f35-46c6-4633-b39b-bd238e85b022","commandId":"ui-implement-2","operation":"run","headSha":"7b77018b6fefb54423442e83f9b04ba27e4560a9","command":"mkdir -p src/ui && cat > src/ui/index.ts <<'EOF'
import type { ControlScheme, PlayerProfile } from '../contracts';
import { GAME_CONFIG } from '../config/GameConfig';
import './ui.css';

type Screen='main'|'play'|'custom'|'ranked'|'settings'|'profile';
type Mode='play'|'custom'|'ranked';
export interface UISettings { controlScheme:ControlScheme; quality:'low'|'medium'|'high'|'ultra'; volume:number; reducedMotion:boolean }
export interface SetupDTO { players:number; bots:number; holes:9|18; courseId:string }
export interface ProfileDTO extends PlayerProfile { level:number; xp:number; xpNext:number; matches:number; wins:number; bestRound:number }
export interface UIActions { navigate?(screen:Screen):void; startMatch?(mode:Mode,setup:SetupDTO):void; saveSettings?(settings:UISettings):void }

const profile:ProfileDTO={id:'local-player',displayName:'Putt Pilot',kind:'human',ballStyleId:'classic-white',rating:1240,level:7,xp:680,xpNext:1000,matches:34,wins:11,bestRound:31};
const esc=(s:string)=>s.replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]!));
const nav=(label:string,to:Screen,primary=false)=>`<button class="cpa-btn ${primary?'primary':''}" data-nav="${to}">${label}</button>`;
const setup=(mode:Mode)=>`<section class="cpa-screen"><header>${nav('← Back','main')}<b>MATCH SETUP</b></header><main class="cpa-card"><h2>${mode==='ranked'?'Ranked Match':mode==='custom'?'Custom Game':'Quick Play'}</h2><p>${mode==='ranked'?'Competitive rules are fixed for fair rating play.':'Choose your match and hit the green.'}</p><div class="cpa-grid"><label>Players<select name="players" ${mode==='ranked'?'disabled':''}>${[1,2,3,4,5,6,7,8].map(n=>`<option ${n===4?'selected':''}>${n}</option>`).join('')}</select></label><label>Bot rivals<select name="bots" ${mode==='ranked'?'disabled':''}>${[0,1,2,3,4,5,6,7].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></label><label>Holes<select name="holes" ${mode==='ranked'?'disabled':''}><option>9</option><option>18</option></select></label><label>Course<select name="course" ${mode==='ranked'?'disabled':''}><option value="starter-tour">Skyline Circuit</option><option value="random">Random Tour</option></select></label></div><button class="cpa-btn primary wide" data-start="${mode}">${mode==='ranked'?'Find Match':'Start Match'}</button></main></section>`;

export class AppUI {
 private screen:Screen='main'; private settings:UISettings={controlScheme:'drag-power',quality:'high',volume:80,reducedMotion:false};
 constructor(private root:HTMLElement,private actions:UIActions={}){this.render()}
 navigate=(s:Screen)=>{this.screen=s;this.actions.navigate?.(s);this.render()};
 private view(){if(this.screen==='main')return `<section class="cpa-screen main"><div class="hero"><small>ARCADE MINI GOLF</small><h1>${GAME_CONFIG.title}</h1><p>Master wild courses. Outsmart rivals. Chase the perfect putt.</p></div><nav>${nav('Play','play',true)}${nav('Ranked','ranked')}${nav('Custom Game','custom')}${nav('Profile','profile')}${nav('Settings','settings')}</nav><aside><strong>${esc(profile.displayName)}</strong><span>Rating ${profile.rating} · Lv. ${profile.level}</span></aside></section>`;if(this.screen==='settings')return `<section class="cpa-screen"><header>${nav('← Back','main')}<b>PREFERENCES</b></header><form class="cpa-card form" data-settings><h2>Settings</h2><label>Shot controls<select name="controls"><option value="drag-power">Drag to aim & power</option><option value="hold-to-charge">Hold to charge</option></select></label><label>Graphics<select name="quality"><option>low</option><option>medium</option><option selected>high</option><option>ultra</option></select></label><label>Master volume <output>${this.settings.volume}%</output><input name="volume" type="range" min="0" max="100" value="${this.settings.volume}"></label><label class="check"><input name="motion" type="checkbox"> Reduce interface motion</label><button class="cpa-btn primary" type="submit">Save settings</button></form></section>`;if(this.screen==='profile'){const rate=Math.round(profile.wins/profile.matches*100),xp=Math.round(profile.xp/profile.xpNext*100);return `<section class="cpa-screen"><header>${nav('← Back','main')}<b>PLAYER PROFILE</b></header><main class="cpa-card"><h2>${esc(profile.displayName)}</h2><p>Level ${profile.level} · Rating ${profile.rating}</p><div class="xp"><i style="width:${xp}%"></i></div><p>${profile.xp} / ${profile.xpNext} XP</p><div class="stats"><div><b>${profile.matches}</b>Matches</div><div><b>${profile.wins}</b>Wins</div><div><b>${rate}%</b>Win rate</div><div><b>${profile.bestRound}</b>Best round</div></div></main></section>`}return setup(this.screen)}
 private render(){this.root.innerHTML=this.view();this.root.querySelectorAll<HTMLElement>('[data-nav]').forEach(x=>x.onclick=()=>this.navigate(x.dataset.nav as Screen));const range=this.root.querySelector<HTMLInputElement>('input[type=range]');if(range)range.oninput=()=>{const o=range.parentElement?.querySelector('output');if(o)o.textContent=range.value+'%'};const form=this.root.querySelector<HTMLFormElement>('[data-settings]');if(form)form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);this.settings={controlScheme:String(f.get('controls')) as ControlScheme,quality:String(f.get('quality')) as UISettings['quality'],volume:Number(f.get('volume')),reducedMotion:f.get('motion')==='on'};this.actions.saveSettings?.(this.settings);this.navigate('main')};const start=this.root.querySelector<HTMLElement>('[data-start]');if(start)start.onclick=()=>{const mode=start.dataset.start as Mode;const get=(n:string)=>this.root.querySelector<HTMLSelectElement>(`[name="${n}"]`)?.value;this.actions.startMatch?.(mode,{players:Number(get('players')||4),bots:Number(get('bots')||3),holes:Number(get('holes')||9) as 9|18,courseId:get('course')||'starter-tour'})}}
}
EOF
cat > src/ui/ui.css <<'EOF'
.cpa-layer{position:fixed;inset:0;z-index:10;overflow:auto;color:#f5fbff;background:radial-gradient(circle at 75% 15%,#174c46 0,transparent 30%),linear-gradient(135deg,#07111f,#0b2134);font-family:Inter,system-ui,sans-serif;touch-action:manipulation}.cpa-screen{box-sizing:border-box;min-height:100%;max-width:1200px;margin:auto;padding:clamp(24px,5vw,70px)}.cpa-screen.main{display:flex;align-items:center;gap:clamp(36px,8vw,120px)}.hero{flex:1}.hero small,.cpa-screen header b{color:#6ee7b7;letter-spacing:.2em;font-size:12px}.hero h1,.cpa-card h2{font-size:clamp(42px,7vw,88px);line-height:.92;letter-spacing:-.05em;margin:.15em 0}.hero p,.cpa-card p{color:#a8bbca;line-height:1.6}.cpa-screen nav{width:min(380px,100%);display:grid;gap:12px}.cpa-btn{min-height:52px;padding:0 20px;border:1px solid #ffffff25;border-radius:14px;background:#ffffff0e;color:inherit;font:inherit;font-weight:750;text-align:left;cursor:pointer}.cpa-btn:hover,.cpa-btn:focus-visible{background:#ffffff1c;outline:2px solid #6ee7b7;outline-offset:2px}.cpa-btn.primary{background:#6ee7b7;color:#062119;border:0}.wide{width:100%;text-align:center;margin-top:24px}.cpa-screen aside{position:absolute;top:28px;right:32px;display:grid}.cpa-screen aside span{color:#91a7b9;font-size:12px}.cpa-screen header{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.cpa-card{max-width:760px;margin:auto;padding:clamp(24px,4vw,48px);border:1px solid #ffffff20;border-radius:24px;background:#0d2236dd}.cpa-card h2{font-size:clamp(36px,5vw,58px)}.cpa-grid,.form{display:grid;grid-template-columns:1fr 1fr;gap:18px}.cpa-grid label,.form label{display:grid;gap:8px;color:#b8c7d3;font-size:13px;font-weight:700}.cpa-grid select,.form select{min-height:48px;border:1px solid #ffffff25;border-radius:12px;padding:0 12px;background:#102a40;color:white}.form h2,.form button,.form .check{grid-column:1/-1}.form input[type=range]{width:100%;accent-color:#6ee7b7}.xp{height:10px;border-radius:9px;background:#172e42;overflow:hidden}.xp i{display:block;height:100%;background:#6ee7b7}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:28px}.stats div{padding:18px;background:#ffffff0c;border-radius:14px;color:#91a7b9;font-size:12px}.stats b{display:block;color:white;font-size:28px;margin-bottom:4px}@media(max-width:760px){.cpa-screen.main{display:block;padding-top:110px}.cpa-screen nav{margin-top:36px}.cpa-screen aside{left:24px;right:auto}.cpa-grid,.form{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.cpa-btn{min-height:56px}}@media(prefers-reduced-motion:reduce){.cpa-layer *{scroll-behavior:auto!important;transition:none!important}}
EOF
cat > src/ui/domTests.ts <<'EOF'
import { AppUI } from './index';
export function runUIDOMSmokeTests(){const root=document.createElement('div');new AppUI(root);const must=(q:string)=>{if(!root.querySelector(q))throw new Error('UI smoke test missing '+q)};must('[data-nav="play"]');must('[data-nav="ranked"]');must('[data-nav="custom"]');(root.querySelector('[data-nav="settings"]') as HTMLElement).click();must('[data-settings]');must('[name="controls"]');(root.querySelector('[data-nav="main"]') as HTMLElement).click();(root.querySelector('[data-nav="profile"]') as HTMLElement).click();must('.stats');return true}
EOF
