p='src/main.ts'
s=open(p).read()
s=s.replace("import './style.css';", "import './style.css';\nimport { AppUI } from './ui';")
s=s.replace('root.append(renderer.domElement);', "root.append(renderer.domElement);\nconst uiRoot = document.createElement('div');\nuiRoot.className = 'cpa-layer';\nroot.append(uiRoot);\nnew AppUI(uiRoot);")
open(p,'w').write(s)
